    Iter mid = d.start + 7;
    d.fill_insert(mid, 2, a);                             // middle: deferred to _M_insert_aux
    if (g_aux != 1 || d.size() != 26) ok = 0;
    if (!ok) { std::printf("00a0faa0_TEST FAIL\n"); return 1; }
    std::printf("00a0faa0_TEST PASS\n");
    return 0;
}

